import type { BankQuestion } from "@/lib/bank";

/** Soils, Agriculture and Irrigation (Geography): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "geo-soils-agriculture-1", "question": "“Regur” is another name for which soil?", "options": ["Black soil", "Red soil", "Laterite soil", "Alluvial soil"], "answer": 0, "explanation": "Black soil of the Deccan is called regur (and black cotton soil); it forms from the weathering of basalt.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-2", "question": "Which of these is a kharif crop?", "options": ["Wheat", "Mustard", "Rice", "Gram"], "answer": 2, "explanation": "Kharif crops are sown with the onset of the monsoon (June–July); rice is the main one. Wheat, mustard and gram are rabi crops.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-3", "question": "The Green Revolution of the late 1960s brought the biggest early gains in the production of:", "options": ["Oilseeds", "Pulses", "Wheat", "Jute"], "answer": 2, "explanation": "High-yielding dwarf wheat varieties, with irrigation and fertilisers, raised wheat output sharply in Punjab, Haryana and western UP; pulses lagged behind.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-4","question":"Who is widely regarded as the father of the Green Revolution in India?","options":["Vikram Sarabhai","M. S. Swaminathan","Verghese Kurien","Norman E. Borlaug"],"answer":1,"explanation":"M. S. Swaminathan led the spread of high-yielding wheat and rice varieties in India and is called the father of its Green Revolution. Norman Borlaug bred the Mexican dwarf wheats and is the father of the global Green Revolution, the usual trap; Kurien led the White Revolution.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-5", "question": "Watermelon, muskmelon and cucumber grown between the rabi and kharif seasons (roughly March–June) are called:", "options": ["Kharif crops", "Plantation crops", "Zaid crops", "Rabi crops"], "answer": 2, "explanation": "The short summer season between rabi and kharif is the zaid season; melons, cucumber and fodder crops are typical.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-6","question":"Cashew nut grows best on which soil?","options":["Alluvial soil","Red laterite soil","Black cotton soil","Saline soil"],"answer":1,"explanation":"Red laterite soils of Tamil Nadu, Andhra Pradesh and Kerala, well drained and on slopes, suit cashew; with manuring they also support tea and coffee.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-7", "question": "Which soil develops deep, wide cracks in the dry season and is described as “self-ploughing”?", "options": ["Black soil", "Red soil", "Laterite soil", "Mountain soil"], "answer": 0, "explanation": "Black soil is rich in clay that swells when wet and shrinks when dry, opening cracks that let air in; this is why it is called self-ploughing.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-8", "question": "Rabi crops are generally sown in ___ and harvested in ___.", "options": ["October–December; April–June", "March–April; June", "July–August; December", "June–July; September–October"], "answer": 0, "explanation": "Rabi crops are sown in winter (October–December) and harvested in summer (April–June); kharif crops are sown with the monsoon and harvested in September–October.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id":"geo-soils-agriculture-9","question":"“Jhum”, a form of slash-and-burn shifting cultivation, is practised mainly in:","options":["The canal-fed Punjab plains","The salt flats of the Rann","The islands of the Ganga delta","The north-eastern hill states"],"answer":3,"explanation":"Jhum is practised in the hills of Assam, Meghalaya, Mizoram, Nagaland and other north-eastern states; forest is cleared, burnt, cropped for a few years and then left to recover.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-10", "question": "Which of these conditions is NOT suitable for a tea plantation?", "options": ["Water standing around the roots", "Deep, fertile soil rich in humus", "Warm, moist, frost-free climate", "Well-drained hill slopes"], "answer": 0, "explanation": "Tea needs heavy, well-distributed rain but water must drain away; waterlogging damages the roots, which is why tea is grown on slopes.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-11", "question": "Terrace farming is practised on hill slopes mainly to:", "options": ["Drain water quickly downhill", "Check soil erosion and run-off", "Increase the salinity of the soil", "Allow shifting cultivation"], "answer": 1, "explanation": "Cutting steps (terraces) on slopes slows running water, holds soil and moisture, and creates flat land for cultivation.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-12", "question": "For orchards in water-scarce, arid areas, the most water-efficient method of irrigation is:", "options": ["Basin irrigation", "Drip irrigation", "Furrow irrigation", "Flood irrigation"], "answer": 1, "explanation": "Drip irrigation delivers water drop by drop to the root zone, cutting evaporation and run-off losses; flood irrigation wastes the most water.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-13", "question": "Which state is the largest producer of coffee in India?", "options": ["Assam", "Tamil Nadu", "Kerala", "Karnataka"], "answer": 3, "explanation": "Karnataka (Kodagu, Chikkamagaluru, Hassan) produces about 70% of India's coffee; Kerala and Tamil Nadu follow. Assam is a tea state.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"geo-soils-agriculture-14","question":"Black soil is generally poor in:","options":["Calcium carbonate","Magnesium","Potash","Phosphorus"],"answer":3,"explanation":"Black soil is rich in calcium carbonate, magnesium, potash and lime but generally poor in phosphoric content, nitrogen and organic matter. Its dark colour suggests it is rich in everything, which is the trap.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-15","question":"Farmers are advised to add gypsum to which kind of soil?","options":["Peaty, waterlogged soil","Acidic forest soil","Saline and alkaline soil","Leached laterite soil"],"answer":2,"explanation":"Saline/alkaline soils (reh, kallar, usar), common where over-irrigation has raised salts, are reclaimed by adding gypsum, which replaces sodium in the soil.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "geo-soils-agriculture-16", "question": "Rice is a major crop in Punjab and Haryana although these states get relatively low rainfall, mainly because of:", "options": ["Black soil that stores water", "Flooding by the Brahmaputra", "Assured canal and tube-well irrigation", "Heavy winter rain from western disturbances"], "answer": 2, "explanation": "Rice needs plenty of water; in Punjab and Haryana it is grown with canal and tube-well irrigation, which has also caused falling water tables.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-17", "question": "Which crop needs a hot, humid climate with rainfall above 200 cm and temperatures above 25 °C?", "options": ["Bajra", "Cotton", "Rubber", "Wheat"], "answer": 2, "explanation": "Rubber is an equatorial crop needing heavy rain and high temperature, grown mainly in Kerala; cotton and bajra need far less rain.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-18","question":"The Bhoodan movement, in which landowners donated land to the landless, was started by Vinoba Bhave in 1951 at:","options":["Bardoli","Paunar (Wardha)","Pochampalli","Champaran"],"answer":2,"explanation":"Vinoba Bhave began Bhoodan at Pochampalli in present-day Telangana in April 1951. Paunar near Wardha was his own ashram, which makes it the tempting trap; Champaran and Bardoli are linked with earlier Gandhian satyagrahas.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-19","question":"Which source provides the largest share of the net irrigated area in India?","options":["Wells and tube-wells","Lift from rivers","Canals from dams and barrages","Tanks and ponds"],"answer":0,"explanation":"Wells and tube-wells (groundwater) irrigate more than 60% of India's net irrigated area; canals come a distant second, and tanks matter mainly in the south.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-20","question":"Tank irrigation is common in peninsular India mainly because:","options":["The region has deep, porous alluvial aquifers","Hard rock limits groundwater and uneven land eases bunding","Rainfall is spread evenly through all the months of the year","The rivers are snow-fed and keep flowing throughout the year"],"answer":1,"explanation":"On the hard crystalline rocks of the peninsula, water does not soak in easily, rivers are seasonal and the undulating terrain allows bunds to store run-off, so tanks are widely used.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-21","question":"The Indira Gandhi Canal, which irrigates north-western Rajasthan, draws its water from:","options":["The Harike barrage on the Sutlej–Beas","The Tehri dam on the Bhagirathi","The Gandhi Sagar dam on the Chambal","The Bhakra dam on the Sutlej in Himachal"],"answer":0,"explanation":"The canal starts at the Harike barrage in Punjab, where the Beas joins the Sutlej, and runs into the Thar desert of Rajasthan.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-22", "question": "Saffron cultivation in India is confined mainly to:", "options": ["Kashmir", "Gujarat", "Kerala", "Assam"], "answer": 0, "explanation": "Saffron is grown mainly on the karewa (lake-deposit) plateaus of Kashmir, especially around Pampore.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-23", "question": "According to NCERT, cotton needs about how many frost-free days to grow well?", "options": ["120", "365", "210", "90"], "answer": 2, "explanation": "Cotton needs high temperature, light rainfall or irrigation, bright sunshine and about 210 frost-free days; it grows well on black cotton soil.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-24", "question": "Rajasthan is the largest producer of which millet?", "options": ["Ragi", "Maize", "Bajra", "Jowar"], "answer": 2, "explanation": "Bajra (pearl millet) grows on sandy and shallow black soils and suits dry Rajasthan; Karnataka leads in ragi and Maharashtra in jowar.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-25", "question": "Match the “revolution” with the sector. A. Yellow Revolution  B. Blue Revolution  C. White Revolution  D. Silver Revolution; 1. Milk  2. Oilseeds  3. Eggs and poultry  4. Fisheries", "options": ["A-3, B-4, C-1, D-2", "A-2, B-3, C-1, D-4", "A-2, B-4, C-1, D-3", "A-2, B-4, C-3, D-1"], "answer": 2, "explanation": "Yellow = oilseeds, Blue = fisheries, White = milk (Operation Flood), Silver = eggs and poultry.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-26", "question": "Match the crop with the state that leads its production. A. Coffee  B. Tea  C. Jute  D. Natural rubber; 1. Kerala  2. West Bengal  3. Karnataka  4. Assam", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-1, B-4, C-2, D-3", "A-2, B-4, C-3, D-1"], "answer": 1, "explanation": "Karnataka leads in coffee, Assam in tea, West Bengal in jute and Kerala in natural rubber.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"geo-soils-agriculture-27","question":"How many of the following statements about Indian soils are correct? I. Laterite soils are poor in nitrogen and rich in iron oxide. II. Black soil has formed from the weathering of the Deccan basalt. III. Red soil develops on crystalline igneous rocks in low-rainfall parts of the eastern and southern Deccan. IV. Desert soils are rich in humus.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: desert soils are sandy and low in humus because there is little vegetation and evaporation is high.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "geo-soils-agriculture-28", "question": "Arrange in chronological order: 1. Launch of Operation Flood  2. National Food Security Act  3. Introduction of high-yielding varieties (start of the Green Revolution)  4. Launch of PM-KISAN", "options": ["2-1-3-4", "2-3-1-4", "3-2-1-4", "3-1-2-4"], "answer": 3, "explanation": "HYV seeds were introduced in 1965–66, Operation Flood began in 1970, the National Food Security Act was passed in 2013 and PM-KISAN started in 2019.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-29", "question": "How many of the following statements about Minimum Support Price (MSP) are correct? I. MSP is announced for both kharif and rabi crops. II. The Commission for Agricultural Costs and Prices is a statutory body. III. For sugarcane, MSP has been replaced by the Fair and Remunerative Price (FRP). IV. MSP is legally guaranteed by an Act of Parliament.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. The CACP is an attached office of the Agriculture Ministry, not a statutory body (II wrong), and MSP has no statutory guarantee (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-soils-agriculture-30", "question": "Which group contains only kharif crops?", "options": ["Rice, barley, groundnut, tur", "Rice, cotton, jute, soybean", "Maize, mustard, cotton, jute", "Soybean, peas, bajra, jute"], "answer": 1, "explanation": "Mustard, barley and peas are rabi crops, which rules out the other three groups; rice, cotton, jute and soybean are all sown with the monsoon.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-31", "question": "Which of these is NOT a coffee-growing region?", "options": ["Chikkamagaluru", "Wayanad", "Dooars", "Kodagu"], "answer": 2, "explanation": "Chikkamagaluru and Kodagu (Karnataka) and Wayanad (Kerala) are coffee areas; the Dooars at the foot of the Himalaya in West Bengal and Assam are known for tea.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-32", "question": "Assertion (A): Black soil can support crops like cotton with little irrigation. Reason (R): Black soil has a high clay content and holds moisture for a long time.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because of its fine clay, black soil retains moisture for long periods, which lets cotton grow in the dry Deccan with limited irrigation.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-soils-agriculture-33", "question": "Match the dam with its river. A. Nagarjuna Sagar  B. Mettur  C. Ukai  D. Gandhi Sagar; 1. Tapi  2. Chambal  3. Krishna  4. Kaveri", "options": ["A-3, B-2, C-1, D-4", "A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Nagarjuna Sagar is on the Krishna, Mettur on the Kaveri, Ukai on the Tapi and Gandhi Sagar on the Chambal.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"geo-soils-agriculture-34","question":"How many of the following statements about the Green Revolution are correct? I. It began in the mid-1960s with high-yielding rice varieties developed in Mexico. II. Its early benefits were concentrated in Punjab, Haryana and western Uttar Pradesh. III. It contributed to regional inequality and to falling groundwater tables. IV. Pulses showed the sharpest rise in production.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"II and III are correct. The varieties developed in Mexico were high-yielding wheat (rice HYVs came from the Philippines), and the gains came mainly in wheat and later rice while pulses stagnated, so I and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "geo-soils-agriculture-35", "question": "Which of the following pairs of crop and season is NOT correctly matched?", "options": ["Ragi — rabi", "Barley — rabi", "Gram — rabi", "Tur (arhar) — kharif"], "answer": 0, "explanation": "Ragi is mainly a kharif millet grown in Karnataka and Tamil Nadu; tur is a kharif pulse, and gram and barley are rabi crops.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-36", "question": "Black soil covers large parts of all of the following EXCEPT:", "options": ["Saurashtra in Gujarat", "The Malwa plateau of Madhya Pradesh", "Assam", "Maharashtra"], "answer": 2, "explanation": "Black soil lies over the Deccan lava region: Maharashtra, Malwa, Saurashtra and parts of Karnataka, Telangana and Andhra Pradesh. Assam has mainly alluvial soil.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-37", "question": "How many of the following statements are correct? I. Wheat needs a cool growing season and bright sunshine when the grain ripens. II. Sugarcane is a tropical and subtropical crop needing about 75–100 cm of rain. III. Tea bushes need frost during the growing season. IV. Maize is grown only as a rabi crop.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. Tea needs a frost-free climate (III wrong), and maize is mainly a kharif crop, though grown in rabi in some states such as Bihar (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-soils-agriculture-38", "question": "Match the soil with its feature. A. Alluvial  B. Black  C. Laterite  D. Red; 1. Colour from iron diffused through crystalline rocks  2. Self-ploughing, with cracks in summer  3. Divided into khadar and bhangar  4. Formed by intense leaching; hardens on exposure and is cut as bricks", "options": ["A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-2, B-3, C-4, D-1", "A-3, B-2, C-4, D-1"], "answer": 3, "explanation": "Alluvial soil is divided into khadar (new) and bhangar (old); black soil is self-ploughing; laterite results from leaching and is used as building brick; red soil gets its colour from iron.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-39", "question": "How many of the following statements are correct? I. The Soil Health Card scheme was launched in 2015. II. “Har Khet Ko Pani” and “More crop per drop” are slogans of the Pradhan Mantri Krishi Sinchayee Yojana. III. The Kisan Credit Card scheme was introduced in 1998. IV. Operation Flood was implemented by the National Dairy Development Board.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: Soil Health Cards began in 2015 at Suratgarh (Rajasthan), PMKSY uses both slogans, KCC dates from 1998, and the NDDB ran Operation Flood.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-soils-agriculture-40", "question": "Identify the crop: it is mainly a kharif oilseed, grows best on well-drained sandy loams with moderate rain, and Gujarat is its largest producer.", "options": ["Sunflower", "Soybean", "Mustard", "Groundnut"], "answer": 3, "explanation": "Groundnut is a kharif oilseed of light sandy soils, led by Gujarat; mustard is a rabi crop of the north, and soybean is concentrated in Madhya Pradesh and Maharashtra.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-soils-agriculture-41", "question": "Which soil covers the largest area of India?", "options": ["Black soil", "Laterite soil", "Alluvial soil", "Desert soil"], "answer": 2, "explanation": "Alluvial soil, laid down by the Indus, Ganga and Brahmaputra systems and in the coastal deltas, covers about 40% of India's area, more than any other soil.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-42","question":"Jute is often called the:","options":["Golden fibre","White gold","Black gold","Silver fibre"],"answer":0,"explanation":"Jute is called the golden fibre for its colour and its value; 'white gold' is a nickname for cotton and 'black gold' for petroleum.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-43", "question": "A farmer who grows crops and also rears cattle and poultry on the same farm practises:", "options": ["Shifting cultivation", "Mixed farming", "Plantation farming", "Nomadic herding"], "answer": 1, "explanation": "Mixed farming combines crop growing with livestock rearing, so the animals give manure and draught power and the crops give fodder.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-44", "question": "Growing two or more crops one after another on the same field in a single year is called:", "options": ["Monoculture", "Ley farming", "Shifting cultivation", "Multiple cropping"], "answer": 3, "explanation": "Multiple cropping raises the cropping intensity of a field, for example rice in kharif followed by wheat in rabi. Monoculture means a single crop year after year.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-45","question":"Soil erosion by wind is most serious in:","options":["The flood-prone Brahmaputra valley","The steep Western Ghats slopes","The arid west of Rajasthan","The tidal Sundarbans islands"],"answer":2,"explanation":"Loose sand, sparse vegetation and strong winds make wind erosion a major problem in the Thar region; elsewhere running water is the main agent.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-46","question":"Laterite soils develop mainly under:","options":["Cold, dry conditions with very little leaching","Heat and heavy seasonal rain causing intense leaching","Waterlogged, marshy conditions with decaying plants","Wind deposition of fine sand in hot deserts"],"answer":1,"explanation":"Heavy rain leaches away silica and lime, leaving iron and aluminium oxides behind. That is why laterites are found on the summits of the Ghats and on the Meghalaya plateau.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-47","question":"Peaty soils, rich in organic matter and often black and acidic, develop mainly in:","options":["The dry interior of the Deccan plateau","The sandy tracts of western Rajasthan","The cold desert of Ladakh","Badly drained humid coasts and deltas"],"answer":3,"explanation":"Heavy rain and waterlogging let dead plant matter pile up faster than it decomposes, forming peaty soils. Dry regions cannot build up such organic matter.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-48","question":"The deep ravines along the Chambal river are the result of:","options":["Sheet erosion by rain","Wind erosion and deflation","Gully erosion by running water","Glacial erosion in the Ice Age"],"answer":2,"explanation":"Running water cuts deep channels (gullies) in soft soil; these widen into the badlands of the Chambal. Sheet erosion removes a thin layer evenly over a wide area.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-49", "question": "Which of these is a rabi oilseed?", "options": ["Groundnut", "Mustard", "Soybean", "Sesamum grown in the monsoon"], "answer": 1, "explanation": "Rapeseed-mustard is sown in October–November and harvested in spring, mainly in Rajasthan, Haryana and Uttar Pradesh. Groundnut and soybean are kharif crops.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-50","question":"Which of these is NOT a feature of plantation agriculture?","options":["A single crop grown on a large estate","Large capital investment and hired labour","Produce grown mainly for sale and processing","Small family plots growing food for the home"],"answer":3,"explanation":"Plantations such as tea, coffee and rubber are large, capital-intensive, single-crop estates for the market. Family plots for home consumption describe subsistence farming.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-51","question":"Intensive subsistence farming, where high doses of inputs and labour are used on small plots, is typical of:","options":["Thinly populated areas with large farms","Densely populated areas where land is scarce","Cold deserts with a very short growing season","Commercial ranching areas of the grasslands"],"answer":1,"explanation":"Where land is scarce, farmers use heavy labour, manure and irrigation to get the most from a small plot, as on the rice fields of the Ganga plain and coastal deltas.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-52", "question": "Canals drawn from rivers through barrages or weirs that supply water throughout the year are called:", "options": ["Perennial canals", "Inundation canals", "Distributaries of tanks", "Karez channels"], "answer": 0, "explanation": "Perennial canals have a regulated, year-round supply from snow-fed or dammed rivers. Inundation canals carry water only when the river is in flood.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-53","question":"Shifting cultivation is known as 'Podu' in:","options":["Andhra Pradesh and Odisha","Mizoram and Manipur","Punjab and Haryana","Madhya Pradesh"],"answer":0,"explanation":"The slash-and-burn practice is called Podu in Andhra Pradesh and Odisha, Jhum in the north-east and Bewar or Dahiya in Madhya Pradesh.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-soils-agriculture-54","question":"Indian agriculture has been called a 'gamble on the monsoon' mainly because:","options":["Most crops are grown only in the dry winter season","Most farmland is rain-fed, so output tracks rainfall","India has almost no irrigation canals, tanks or wells","The monsoon brings frost and hail every year"],"answer":1,"explanation":"A large share of the net sown area still depends on rainfall, so a weak or erratic monsoon cuts kharif output and farm incomes.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id": "geo-soils-agriculture-55", "question": "Red soil appears yellow when:", "options": ["It is hydrated", "It is rich in humus", "It is waterlogged with salt", "It contains lime nodules"], "answer": 0, "explanation": "Red soil gets its colour from iron diffused through crystalline rocks; in hydrated form the iron oxide gives a yellow colour, hence 'red and yellow soils'.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-56","question":"In the snow-bound areas of the high Himalaya, soils are typically:","options":["Rich in humus and strongly alkaline","Thick, deep and highly fertile","Saline and rich in sodium salts","Acidic, low in humus and denuded"],"answer":3,"explanation":"NCERT notes that soils of the snow-bound Himalaya undergo denudation and are acidic with low humus; the deeper, fertile forest soils occur lower down on valley slopes.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-57","question":"Saline and alkaline soils are locally known as:","options":["Regur and kankar","Khadar and bhangar","Reh, kallar and usar","Bhabar, terai and duar"],"answer":2,"explanation":"Reh, kallar and usar are local names for salt-affected, infertile soils in Uttar Pradesh, Punjab and Haryana. Regur is black soil, and khadar/bhangar are new and old alluvium.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-58", "question": "Which state is the largest producer of mulberry silk in India?", "options": ["Assam", "Karnataka", "West Bengal", "Jammu and Kashmir"], "answer": 1, "explanation": "Karnataka, around Ramanagara and Mysuru, produces the largest share of India's mulberry silk. Assam is known for muga and eri silk rather than mulberry.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-59", "question": "The Planning Commission divided India into how many agro-climatic regions for agricultural planning?", "options": ["8", "10", "15", "20"], "answer": 2, "explanation": "The Planning Commission (1988–89) identified 15 agro-climatic regions based on soil, climate, physiography and water resources. Eight is the number of major soil groups in the NCERT classification.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-60", "question": "Coffee cultivation in India began with Arabica seeds that Baba Budan is said to have brought from Yemen and planted in the hills of:", "options": ["The Nilgiris, Tamil Nadu", "Kodagu (Coorg), Karnataka", "Wayanad, Kerala", "Chikkamagaluru, Karnataka"], "answer": 3, "explanation": "The Baba Budan hills near Chikkamagaluru are where coffee is said to have first been grown in India, from Arabica seeds brought from Yemen.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-61","question":"In the production of fruits and vegetables, India ranks:","options":["Second in the world, after China","First in the world, ahead of China","Third, after China and the USA","Fifth in the world, after Brazil"],"answer":0,"explanation":"India is the world's second largest producer of both fruits and vegetables, behind China.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-62", "question": "According to NCERT, dryland farming is largely confined to regions that receive annual rainfall of less than:", "options": ["25 cm", "75 cm", "150 cm", "200 cm"], "answer": 1, "explanation": "Dryland farming, with hardy crops like ragi, bajra, moong, gram and guar, is found where rainfall is below about 75 cm; wetland farming is where rain exceeds the crops' needs.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-63", "question": "Which of the following is NOT one of the eight major soil groups in the NCERT classification of Indian soils?", "options": ["Peaty soil", "Saline soil", "Podzol", "Forest soil"], "answer": 2, "explanation": "NCERT lists alluvial, black, red and yellow, laterite, arid, saline, peaty and forest soils. Podzols are soils of cool, coniferous regions and are not among them.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-64","question":"Identify the crop: it is a rabi pulse grown largely on residual moisture in Madhya Pradesh, Maharashtra and Rajasthan, and India is the world's largest producer of it.","options":["Arhar (pigeon pea)","Urad (black gram)","Moong (green gram)","Gram (chickpea)"],"answer":3,"explanation":"Gram is a rabi pulse of drier areas grown on residual soil moisture, and India is its largest producer. Arhar, urad and moong are mainly kharif pulses; do not let the word 'gram' in their English names mislead you.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-65","question":"Which of these is NOT a millet?","options":["Sorghum","Barley","Bajra","Ragi"],"answer":1,"explanation":"Sorghum (jowar), bajra and ragi are millets, hardy grains of dry areas. Barley is a temperate rabi cereal, not a millet.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-66","question":"Sprinkler irrigation is especially suited to:","options":["Sandy soils and uneven land","Clayey soils in flat river deltas","Paddy fields that need standing water","Saline marshes near the coast"],"answer":0,"explanation":"Sprinklers spray water like rain, so they work on light, sandy soils and undulating land where water would run off or seep away under flood irrigation.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-67", "question": "Which state was declared India's first fully organic state in 2016?", "options": ["Kerala", "Himachal Pradesh", "Mizoram", "Sikkim"], "answer": 3, "explanation": "Sikkim converted all its farmland to certified organic farming and was declared fully organic in 2016.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-68", "question": "Match the traditional water-harvesting system with its region. A. Kuls  B. Zings  C. Eris  D. Khadins; 1. Ladakh  2. Western Himalaya (Himachal Pradesh)  3. Jaisalmer, Rajasthan  4. Tamil Nadu", "options": ["A-1, B-2, C-4, D-3", "A-2, B-1, C-3, D-4", "A-2, B-1, C-4, D-3", "A-2, B-4, C-1, D-3"], "answer": 2, "explanation": "Kuls are diversion channels of the western Himalaya, zings are glacier-melt tanks in Ladakh, eris are tanks of Tamil Nadu and khadins are runoff-harvesting fields of Jaisalmer.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-69","question":"How many of the following statements about alluvial soils are correct? I. Khadar is the older alluvium lying above the flood level. II. Alluvial soils are generally rich in phosphorus but poor in potash. III. Bhangar, the older alluvium, contains kankar nodules. IV. Alluvial soils are absent from the Brahmaputra valley.","options":["Only 1","Only 2","All 4","Only 3"],"answer":0,"explanation":"Only III is correct. Khadar is the newer alluvium renewed by floods; alluvial soils are generally rich in potash but poor in phosphorus (not the reverse); and the Brahmaputra valley is a major alluvial plain.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-70", "question": "Match the crop with the state that leads its production. A. Sugarcane  B. Ragi  C. Rapeseed-mustard  D. Apple; 1. Jammu and Kashmir  2. Rajasthan  3. Karnataka  4. Uttar Pradesh", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Uttar Pradesh leads in sugarcane, Karnataka in ragi, Rajasthan in rapeseed-mustard and Jammu and Kashmir in apples.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-71", "question": "Assertion (A): Pulses are often grown in rotation with cereals. Reason (R): Leguminous crops fix atmospheric nitrogen through bacteria in their root nodules.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Rhizobium bacteria in the root nodules of legumes fix nitrogen, restoring soil fertility for the next cereal crop. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-72", "question": "Assertion (A): Shifting cultivation leads to deforestation and soil erosion. Reason (R): Shifting cultivation is practised mainly in the Indo-Gangetic plain.", "options": ["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], "answer": 1, "explanation": "A is true: forest is cleared and burnt and the bare slopes erode. R is false: shifting cultivation is found mainly in the north-eastern hills and the forested tribal belts of Odisha, Andhra Pradesh and Madhya Pradesh, not the plains.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-73","question":"How many of the following are sound methods of soil conservation? I. Contour ploughing on hill slopes. II. Shifting (jhum) cultivation on steep hill slopes. III. Burning crop stubble after harvest. IV. Ploughing up and down the slope.","options":["Only 1","Only 3","Only 2","All 4"],"answer":0,"explanation":"Only I is a conservation method; contour ploughing checks runoff. Jhum clears forest cover from slopes, stubble burning destroys organic matter and soil life, and ploughing up and down the slope makes channels that speed erosion.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-74", "question": "Match the term with what it involves. A. Ratooning  B. Viticulture  C. Apiculture  D. Pisciculture; 1. Grapes  2. Honey bees  3. Fish  4. Raising a new crop from the stubble of the old one, as in sugarcane", "options": ["A-4, B-2, C-1, D-3", "A-4, B-1, C-3, D-2", "A-1, B-4, C-2, D-3", "A-4, B-1, C-2, D-3"], "answer": 3, "explanation": "A ratoon crop grows from the stubble left after harvest, common in sugarcane; viticulture is grape growing, apiculture is bee-keeping and pisciculture is fish farming.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-75","question":"Which pair of crop and its category is NOT correct?","options":["Jowar — coarse cereal","Masoor — pulse","Castor — non-edible oilseed","Mesta — beverage crop"],"answer":3,"explanation":"Mesta (kenaf) is a fibre crop grown like jute, not a beverage crop. Jowar is a coarse cereal (millet), masoor a rabi pulse and castor a non-edible oilseed.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-76","question":"How many of the following statements about crop requirements are correct? I. Rice needs temperatures above 25 °C, high humidity and rainfall above about 100 cm. II. Maize grows well in old alluvial soil at temperatures of about 21–27 °C. III. Jute grows best on fertile flood-plain soils that are renewed every year. IV. Wheat needs a cool growing season and bright sunshine at the time of ripening.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct. Rice needs heat, humidity and heavy rain; maize suits old alluvium at 21–27 °C; jute prefers annually renewed flood-plain soils; and wheat, a rabi crop, needs a cool growing season and bright sun at ripening.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-77", "question": "Arrange in chronological order: 1. Approval of Bt cotton for commercial cultivation  2. Setting up of NABARD  3. Launch of PM-KISAN  4. Setting up of the (Imperial) Council of Agricultural Research, now ICAR", "options": ["4-2-1-3", "2-4-1-3", "4-1-2-3", "4-2-3-1"], "answer": 0, "explanation": "ICAR began as the Imperial Council of Agricultural Research in 1929, NABARD was set up in 1982, Bt cotton was approved in 2002 and PM-KISAN started in 2019.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-78","question":"How many of the following statements about Kuttanad are correct? I. It is a region of Kerala where farming is done below sea level. II. The FAO has recognised it as a Globally Important Agricultural Heritage System. III. Many of its soils are acidic and peaty. IV. It lies in the rain shadow of the Western Ghats and gets scanty rain.","options":["Only 1","Only 3","Only 2","All 4"],"answer":1,"explanation":"I, II and III are correct. Kuttanad, in the backwaters around Vembanad lake, gets heavy rain from the south-west monsoon, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-79", "question": "Match the rice crop of West Bengal with its season. A. Aus  B. Aman  C. Boro; 1. Main winter rice, sown with the monsoon and harvested in November–December  2. Summer rice, sown in winter under irrigation and harvested in April–May  3. Autumn rice, sown in pre-monsoon showers and harvested in August–September", "options": ["A-1, B-3, C-2", "A-3, B-1, C-2", "A-3, B-2, C-1", "A-2, B-1, C-3"], "answer": 1, "explanation": "Aus is the autumn crop, Aman the main winter (kharif) crop and Boro the irrigated summer crop. Aman covers the largest area.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-80", "question": "Assertion (A): Waterlogging and soil salinity have become serious problems in parts of canal-irrigated Punjab and Haryana. Reason (R): Over-irrigation raises the water table, and capillary action brings salts to the surface.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Heavy canal irrigation without drainage raises the water table; as water evaporates, salts are left on the surface. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-81", "question": "Match the soil with the region where it is typically found. A. Laterite  B. Arid  C. Saline  D. Forest; 1. Western Rajasthan  2. Rann of Kutch  3. Summits of the Western and Eastern Ghats  4. Himalayan slopes", "options": ["A-3, B-1, C-2, D-4", "A-3, B-2, C-1, D-4", "A-4, B-1, C-2, D-3", "A-3, B-1, C-4, D-2"], "answer": 0, "explanation": "Laterites cap the Ghats summits, arid soils cover western Rajasthan, saline soils occur in the Rann of Kutch and coastal marshes, and forest soils develop on Himalayan slopes.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-82", "question": "Which pair of crop and the soil it is best suited to is NOT correct?", "options": ["Cotton — black soil", "Tea — well-drained, slightly acidic hill soil", "Jute — fertile alluvial delta soil", "Rice — porous sandy desert soil"], "answer": 3, "explanation": "Rice needs standing water, so it prefers clayey alluvial soils that hold water; porous desert sand drains too fast. The other pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-83", "question": "How many of the following are rabi crops? I. Barley  II. Gram  III. Linseed  IV. Peas", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are sown in October–December and harvested in spring, so they are rabi crops.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-84","question":"How many of the following pulses are grown mainly as kharif crops? I. Arhar (tur)  II. Moong  III. Urad  IV. Moth","options":["Only 3","Only 2","Only 1","All 4"],"answer":3,"explanation":"All four are kharif pulses sown with the monsoon: arhar, moong, urad and moth (a drought-hardy pulse of Rajasthan). Rabi pulses include gram and masoor (lentil).","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-85", "question": "Match the research institute with its location. A. Indian Agricultural Research Institute  B. National Rice Research Institute  C. Central Potato Research Institute  D. Indian Institute of Sugarcane Research; 1. Shimla  2. Lucknow  3. New Delhi  4. Cuttack", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-2, B-4, C-1, D-3", "A-3, B-4, C-2, D-1"], "answer": 1, "explanation": "IARI (Pusa) is in New Delhi, NRRI (formerly CRRI) in Cuttack, CPRI in Shimla and IISR in Lucknow.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-86", "question": "Which crop is the staple food of most people in eastern and southern India?", "options": ["Rice", "Wheat", "Barley", "Maize"], "answer": 0, "explanation": "Rice, a kharif crop of hot, wet areas, is the main cereal of the east, the south and the coasts; wheat dominates in the drier north-west.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "geo-soils-agriculture-87", "question": "Urea is applied to crops mainly to supply which nutrient?", "options": ["Phosphorus", "Nitrogen", "Potassium", "Calcium"], "answer": 1, "explanation": "Urea contains about 46% nitrogen, the nutrient most needed for leafy growth. DAP supplies phosphorus and muriate of potash supplies potassium.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id":"geo-soils-agriculture-88","question":"The main benefit of crop rotation is that it:","options":["Lets the farmer use more chemical fertiliser","Keeps the soil permanently waterlogged","Maintains fertility and breaks pest cycles","Removes the need to plough the field every year"],"answer":2,"explanation":"Changing crops season to season, especially bringing in legumes, restores nitrogen and denies pests a constant host. Growing the same crop repeatedly drains the same nutrients.","difficulty":"moderate","source":"SSC CGL · State PSC"},
  {"id":"geo-soils-agriculture-89","question":"Mulching in agriculture means:","options":["Spraying pesticides from the air on crops","Flooding a field before sowing the seed","Deep ploughing to bring up the subsoil","Covering soil with straw or plastic sheet"],"answer":3,"explanation":"A mulch layer cuts evaporation, keeps soil temperature even, suppresses weeds and reduces erosion by rain splash.","difficulty":"moderate","source":"SSC CGL · State PSC"},
  {"id": "geo-soils-agriculture-90", "question": "To correct a strongly acidic soil, farmers are generally advised to add:", "options": ["Lime", "Gypsum", "Common salt", "Sulphur"], "answer": 0, "explanation": "Lime (calcium carbonate) neutralises acidity and raises pH. Gypsum is used for alkaline (sodic) soils, and sulphur would make the soil more acidic.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id":"geo-soils-agriculture-91","question":"Agroforestry refers to:","options":["Clearing forests to grow crops on the land","Growing trees with crops or livestock together","Planting only fruit orchards on farm land","Growing crops inside reserved forest areas"],"answer":1,"explanation":"Agroforestry deliberately mixes trees with crops or pasture, giving timber, fodder and fruit while improving soil and microclimate. It is the opposite of clearing forest.","difficulty":"moderate","source":"SSC CGL · State PSC"},
  {"id":"geo-soils-agriculture-92","question":"Azolla is grown in paddy fields as a biofertiliser because:","options":["It kills the stem borers of rice","It releases potassium from the rocks","Its partner Anabaena fixes nitrogen","It makes acidic paddy soil alkaline"],"answer":2,"explanation":"Azolla is a small floating fern that houses Anabaena azollae in its leaves; this partnership fixes nitrogen that becomes available to rice when the fern decomposes.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-93", "question": "Which of these crops uses the C4 pathway of photosynthesis, which suits hot, sunny conditions?", "options": ["Wheat", "Rice", "Gram", "Maize"], "answer": 3, "explanation": "Maize, sugarcane, sorghum and pearl millet are C4 plants that fix carbon efficiently in heat and strong light with less water loss. Wheat, rice and gram are C3 crops.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-94","question":"“Fertigation” means:","options":["Supplying fertiliser through irrigation water","Spraying fertiliser from drones only","Burning crop residue to add ash to the soil","Using fertiliser made from fish waste"],"answer":0,"explanation":"In fertigation, dissolved fertilisers are fed into the drip or sprinkler line so they reach the root zone in small, timed doses, saving both water and nutrients.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-95","question":"Hydroponics is a method of:","options":["Growing plants in flooded fields only","Growing plants in nutrient solution, no soil","Irrigating crops using desalinated sea water","Breeding fish in flooded paddy fields"],"answer":1,"explanation":"In hydroponics roots sit in a nutrient solution or inert medium instead of soil. Raising fish in paddy fields is rice–fish culture, a different practice.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-96","question":"The “Happy Seeder” machine promoted in Punjab and Haryana helps farmers to:","options":["Harvest wheat and rice in one pass","Spray pesticides at night with drones","Drill wheat into rice stubble without burning","Transplant rice seedlings by machine"],"answer":2,"explanation":"The Happy Seeder cuts and lifts the paddy straw and drills wheat seed into the soil in one pass, so the straw becomes mulch instead of being burnt, which feeds north India's winter smog.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-97","question":"The System of Rice Intensification (SRI) involves:","options":["Keeping fields flooded and planting old seedlings in clumps","Sowing rice only by broadcasting dry seed on the field","Growing rice only in the rabi season under irrigation","Young single seedlings, wide spacing, wet-dry cycles"],"answer":3,"explanation":"SRI uses fewer, younger seedlings, wider spacing and intermittent irrigation instead of standing water, which saves water and seed and often raises yields.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-98", "question": "“Golden Rice” has been genetically engineered to contain:", "options": ["Beta-carotene, a precursor of vitamin A", "Extra iron and zinc", "A gene for pest resistance from Bacillus thuringiensis", "Higher gluten"], "answer": 0, "explanation": "Golden Rice makes beta-carotene in its grain, which gives it a yellow colour and is meant to fight vitamin A deficiency. The Bt gene is used in Bt cotton for pest resistance.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-99","question":"How many of these statements about a soil profile are correct? I. The A horizon is the topsoil, rich in humus and biological activity. II. The B horizon is the subsoil, where minerals washed down from above accumulate. III. The C horizon is the solid, unweathered bedrock. IV. The organic O horizon lies below the bedrock.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"I and II are correct. The C horizon is weathered parent material; solid bedrock is the R layer at the bottom. The O horizon of leaf litter lies at the very top, above the A horizon, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-100", "question": "Match the term with what it deals with. A. Sericulture  B. Olericulture  C. Floriculture  D. Pomology; 1. Vegetables  2. Rearing silkworms  3. Fruits  4. Flowers", "options": ["A-2, B-1, C-4, D-3", "A-1, B-2, C-4, D-3", "A-2, B-3, C-4, D-1", "A-2, B-1, C-3, D-4"], "answer": 0, "explanation": "Sericulture is silk farming, olericulture the growing of vegetables, floriculture of flowers and pomology the science of fruit growing. Olericulture is the usual trap.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-101","question":"How many of these statements about neem-coated urea are correct? I. The neem coating slows the release of nitrogen into the soil. II. It discourages the diversion of subsidised urea to industrial uses. III. In 2015 the government made neem coating mandatory for all domestically produced urea. IV. Urea itself contains about 46% nitrogen.","options":["Only 1","Only 2","All 4","Only 3"],"answer":2,"explanation":"All four are correct. The neem coating acts as a nitrification inhibitor and makes urea unfit for industrial use, it was made mandatory in 2015, and urea carries about 46% nitrogen, the highest of common solid fertilisers.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "geo-soils-agriculture-102", "question": "Arrange these soil particles in increasing order of size: 1. Sand  2. Clay  3. Gravel  4. Silt", "options": ["4-2-1-3", "2-1-4-3", "2-4-1-3", "2-4-3-1"], "answer": 2, "explanation": "Clay particles are under 0.002 mm, silt 0.002–0.05 mm, sand 0.05–2 mm and gravel coarser still. Fine clay holds water and nutrients; sand drains fast.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-103","question":"How many of these statements about millets are correct? I. Most millets tolerate drought and poor soils. II. Ragi (finger millet) is especially rich in calcium. III. Jowar and bajra are C4 crops. IV. Bajra is grown mainly on the sandy soils of Rajasthan, its largest producer.","options":["Only 1","Only 3","Only 2","All 4"],"answer":3,"explanation":"All four are correct. Millets are hardy C4 crops suited to rain-fed dryland farming, ragi is notably rich in calcium, and bajra grows well on sandy soils, with Rajasthan the leading producer.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-104", "question": "Match the soil problem with the usual remedy. A. Alkaline (sodic) soil  B. Acidic soil  C. Sheet erosion on gentle slopes  D. Wind erosion in dry areas; 1. Shelter belts of trees  2. Lime  3. Gypsum  4. Contour bunding", "options": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-3, B-4, C-2, D-1", "A-3, B-2, C-4, D-1"], "answer": 3, "explanation": "Gypsum replaces sodium in sodic soils; lime neutralises acidity; contour bunds slow water running down slopes; rows of trees break wind speed over open dry land.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-soils-agriculture-105", "question": "Assertion (A): The groundwater table has fallen sharply in much of central Punjab. Reason (R): Paddy grown in the hot summer months is irrigated largely by tube-wells, helped by cheap or free farm power.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Water-hungry paddy in a low-rainfall state, pumped from tube-wells with subsidised power, draws out far more groundwater than is recharged. Punjab's law delaying paddy transplanting to mid-June was a response.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-106","question":"How many of these statements about Integrated Pest Management (IPM) are correct? I. It combines biological, cultural, mechanical and need-based chemical methods. II. It uses tools such as pheromone traps to monitor pests. III. Its aim is to wipe out every pest from the field. IV. It encourages natural enemies such as ladybird beetles.","options":["Only 3","Only 1","Only 2","All 4"],"answer":0,"explanation":"I, II and IV are correct. IPM aims to keep pests below the economic threshold level, not to exterminate them; total eradication would need heavy spraying that IPM tries to avoid, so III is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id":"geo-soils-agriculture-107","question":"How many of these statements about the arid soils of western Rajasthan are correct? I. They are sandy, and saline in some areas. II. They are poor in humus and nitrogen, while their phosphate content is normal. III. Their lower horizons often contain kankar layers, because calcium content increases downward, and these restrict infiltration. IV. With irrigation, as in the Indira Gandhi Canal command area, they can be made productive.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Low rainfall and high evaporation leave salts and calcium in the profile; once water is supplied, crops such as wheat and mustard do well, as the canal tracts show.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-108","question":"How many of these statements about laterite soils are correct? I. The name comes from the Latin word 'later', meaning red. II. They form where heavy rain and high temperature leach away iron and aluminium, leaving silica and lime. III. They are naturally rich in nitrogen, phosphorus and potash. IV. Blocks cut from them harden on exposure to air and are used for building.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only IV is correct. 'Later' means brick, not red; leaching removes silica and lime and leaves oxides of iron and aluminium (not the reverse); and laterites are poor in nitrogen, phosphorus and potash.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-109","question":"Consider the following statements: I. Sesamum (til) is a kharif crop in north India but a rabi crop in the south. II. Castor is grown both as a kharif and as a rabi crop. III. In some states such as Bihar, maize is also grown in the rabi season. IV. Mustard is mainly a kharif oilseed. Which of the statements given above are correct?","options":["I and II only","I, II and III only","II and III only","I, II, III and IV"],"answer":1,"explanation":"I, II and III follow NCERT. Rapeseed–mustard is a rabi oilseed of the northern plains, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-110","question":"A district has a net sown area of 150 thousand hectares, of which 60 thousand hectares are sown more than once in the year. Its cropping intensity is:","options":["140%","40%","71.4%","210%"],"answer":0,"explanation":"Gross cropped area = 150 + 60 = 210 thousand ha; cropping intensity = GCA ÷ NSA × 100 = 210/150 × 100 = 140%. 40% is only the share sown more than once, and 71.4% inverts the ratio.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"geo-soils-agriculture-111","question":"In India's nine-fold land-use classification, land left uncultivated for more than one year but less than five years is recorded as:","options":["current fallow","fallow other than current fallow","culturable waste land","land under miscellaneous tree crops"],"answer":1,"explanation":"Current fallow is land left uncultivated for one agricultural year or less; one to five years makes it 'fallow other than current fallow'; beyond five years it becomes culturable waste land.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-112","question":"Match the local name of shifting cultivation with its region. A. Pamlou  B. Dipa  C. Bewar (Dahiya)  D. Kumari; 1. Western Ghats  2. Manipur  3. Madhya Pradesh  4. Bastar (Chhattisgarh) and the Andaman and Nicobar Islands","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"NCERT lists Pamlou in Manipur, Dipa in Bastar and the Andamans, Bewar or Dahiya in Madhya Pradesh and Kumari in the Western Ghats, alongside Jhum in the north-east and Podu in Andhra Pradesh.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-113","question":"The NPK ratio of 4:2:1, often cited as the desirable norm for fertiliser use in India, refers to the proportion of:","options":["nitrogen, P₂O₅ and K₂O applied as nutrients","nitrogen, potassium and phosphorus, in that order","urea, DAP and gypsum by weight of fertiliser","nitrogen, phosphorus and sulphur as elements"],"answer":0,"explanation":"The norm is about nutrient balance: four parts N to two of P₂O₅ to one of K₂O. Cheap, heavily subsidised urea has pushed actual use far towards nitrogen, damaging soil health.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-114","question":"Match the biofertiliser with its role. A. Rhizobium  B. Azotobacter  C. Mycorrhiza (VAM fungi)  D. Blue-green algae such as Anabaena; 1. Free-living nitrogen fixer in the soil  2. Fungus that helps roots absorb phosphorus  3. Nitrogen fixer in the root nodules of legumes  4. Nitrogen fixer in flooded paddy fields","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Rhizobium works only in symbiosis with legumes, Azotobacter fixes nitrogen on its own, mycorrhizal fungi extend the root system for phosphorus uptake, and cyanobacteria thrive in standing water of paddies.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-115","question":"Assertion (A): The same parent rock can give rise to quite different soils in different parts of India. Reason (R): Climate, through temperature and rainfall, strongly controls the weathering and leaching that form soils.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Granite and gneiss weather into red soils in drier areas but laterite where heavy rain leaches them; climate often overrides parent material, which is why NCERT treats it as a key soil-forming factor.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-116","question":"Black pepper, called the 'King of Spices', and small cardamom, the 'Queen of Spices', are both grown mainly in:","options":["the Brahmaputra valley of Assam","the Malwa plateau of Madhya Pradesh","the Western Ghats of Kerala and Karnataka","the Ganga delta of West Bengal"],"answer":2,"explanation":"Both need a warm, humid climate, heavy rain and shade on well-drained hill slopes, conditions found in the Western Ghats, including the Cardamom Hills of Kerala.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-117","question":"Zero Budget Natural Farming, promoted by Subhash Palekar and adopted at scale by Andhra Pradesh, relies chiefly on:","options":["certified organic fertilisers bought from the market","on-farm Jeevamrutha, mulching and no bought inputs","hydroponic cultivation of crops without any soil","genetically modified seeds that need no fertiliser"],"answer":1,"explanation":"'Zero budget' means farmers buy no external inputs; on-farm microbial preparations, mulch and moisture management replace fertilisers and pesticides. Buying organic inputs from the market defeats the idea.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-118","question":"Which statement correctly distinguishes intercropping from mixed cropping?","options":["Intercropping grows crops one after another in a year; mixed cropping grows them together","Intercropping combines crops with livestock, while mixed cropping uses crops alone","Intercropping is practised only on plantations, mixed cropping only on small farms","Intercropping sows crops in set rows; mixed cropping sows a mixture of their seeds"],"answer":3,"explanation":"Both grow crops together, but intercropping keeps them in set rows (for example soybean with maize), making separate fertilising and harvesting easy. Crops in succession is multiple cropping; crops plus livestock is mixed farming.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-119","question":"Growing a leguminous crop such as sunn hemp or dhaincha and ploughing it into the soil before it matures is called:","options":["mulching","composting","green manuring","vermicomposting"],"answer":2,"explanation":"The buried legume adds organic matter and fixed nitrogen, which is green manuring. Mulching covers the soil surface, while composting and vermicomposting decompose waste outside the field before it is applied.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-120","question":"A soil holds 32% water by volume at field capacity and 14% at the permanent wilting point. The water available to plants in a root zone 1 m deep is about:","options":["180 mm","320 mm","140 mm","460 mm"],"answer":0,"explanation":"Available water = field capacity − wilting point = 18% of 1,000 mm = 180 mm. Water below the wilting point is held too tightly for roots, so the full 320 mm is not usable.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-121","question":"Under the size classes used in India's Agriculture Census, a farmer operating 3 hectares is classed as:","options":["small","semi-medium","medium","marginal"],"answer":1,"explanation":"Marginal is below 1 ha, small 1–2 ha, semi-medium 2–4 ha, medium 4–10 ha and large 10 ha or more. Many assume anything above 2 ha is 'medium'.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-122","question":"Assertion (A): The burning of paddy straw in Punjab and Haryana peaks in October–November. Reason (R): Farmers have only a short window between the paddy harvest and the sowing of wheat.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Combine-harvested paddy leaves loose straw, and with wheat due within a few weeks, burning is the quickest way to clear fields; machines such as the Happy Seeder aim to remove this pressure.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-123","question":"How many of these statements about plantation crops are correct? I. Coffee in India is usually grown under the shade of taller trees. II. Robusta coffee is generally grown at higher elevations than Arabica. III. Coffee is a field crop sown afresh every year with the monsoon. IV. Tea gardens need well-drained slopes, since waterlogging around the roots harms the bushes.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"I and IV are correct. Arabica prefers the higher, cooler slopes while Robusta tolerates warmer, lower ones, so II is wrong; coffee is a perennial shrub that bears for decades, not an annual crop, so III is wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"geo-soils-agriculture-124","question":"Jute cultivation is concentrated in the Ganga–Brahmaputra delta mainly because the crop needs:","options":["well-drained laterite soils and a long dry season","flood-renewed alluvium, heat and water for retting","black soil that holds moisture through a dry winter","cool winters with frost to ripen and harden the fibre"],"answer":1,"explanation":"Jute grows fast in hot, humid conditions on flood-renewed alluvium, and the cut stalks must be soaked (retted) in water to free the fibre, which the delta's ponds and channels provide.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-125","question":"'Kari' soils, which are highly acidic and rich in organic matter, are found in:","options":["the tidal islands of the Sundarbans","the Rann of Kachchh","the Terai of Uttarakhand","the Kuttanad region of Kerala"],"answer":3,"explanation":"Kari soils are peaty, waterlogged soils of Kuttanad, where decaying vegetation under water has made them strongly acidic. The Rann is saline, not peaty.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-126","question":"Two fields get the same rainfall. Field X has a sandy soil, and field Y a clay-loam rich in humus. Which statement is correct?","options":["X retains more water, because its large pores can store more of it","Both retain the same amount, since the rainfall on them is equal","Y retains more, as fine clay pores and humus hold water","X retains more water, because sand holds more organic matter"],"answer":2,"explanation":"Water drains quickly through the large pores of sand, while fine pores between clay particles and spongy humus hold it against gravity, giving Y a far higher water-holding capacity.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-127","question":"A crop's area rises by 10% and its yield per hectare falls by 10% in a year. Its production:","options":["is unchanged","rises by 1%","falls by 10%","falls by 1%"],"answer":3,"explanation":"Production = area × yield = 1.10 × 0.90 = 0.99 of the earlier level, a fall of 1%. Adding the percentages (+10 − 10 = 0) ignores their interaction.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-128","question":"The alluvial soils of the northern plains are generally:","options":["rich in phosphorus but poor in potash","rich in nitrogen and humus but poor in lime","rich in potash but poor in phosphorus","rich in iron and aluminium oxides but poor in potash"],"answer":2,"explanation":"NCERT notes that alluvial soils are generally rich in potash and poor in phosphorus. Iron and aluminium oxides characterise laterites.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-129","question":"Match the traditional water-harvesting system with its region. A. Khadin  B. Ahar–pyne  C. Phad  D. Bamboo drip irrigation; 1. Meghalaya  2. South Bihar  3. Western Rajasthan (Jaisalmer)  4. Maharashtra","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"answer":1,"explanation":"Khadins are run-off fields bunded on the low side in Jaisalmer; ahars (reservoirs) and pynes (channels) serve south Bihar; phads are community canal systems of north Maharashtra; bamboo pipes carry stream water in Meghalaya.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-130","question":"Match the fertiliser with the main nutrient(s) it supplies. A. Urea  B. Diammonium phosphate (DAP)  C. Muriate of potash (MOP)  D. Single superphosphate (SSP); 1. Potassium  2. Nitrogen only  3. Phosphorus, with sulphur and calcium  4. Nitrogen and phosphorus","options":["A-4, B-2, C-1, D-3","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Urea is about 46% N; DAP carries both N and P; MOP is potassium chloride; SSP gives phosphorus along with sulphur and calcium from its gypsum content.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-131","question":"Assertion (A): The early gains of the Green Revolution were concentrated in Punjab, Haryana and western Uttar Pradesh. Reason (R): These states have the most extensive black soils in India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"These states lie on alluvium, not black soil; their advantage was assured canal and tube-well irrigation, which the high-yielding wheat varieties and heavy fertiliser doses needed.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-132","question":"Match the livestock breed with its description. A. Gir  B. Sahiwal  C. Tharparkar  D. Murrah; 1. Buffalo breed of Haryana  2. Cattle breed from the Gir forest region of Gujarat  3. Cattle breed of the Thar desert region  4. Cattle breed named after a district of Punjab, now in Pakistan","options":["A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":1,"explanation":"Gir, Sahiwal and Tharparkar are indigenous milch cattle breeds, while Murrah, the best-known Indian dairy buffalo, comes from Haryana. Mixing up buffalo and cattle breeds is the usual trap.","difficulty":"very-hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-133","question":"Match the soil-forming process with the setting where it dominates. A. Laterisation  B. Calcification  C. Podzolisation  D. Salinisation; 1. Cool, humid coniferous forests of the high Himalaya  2. Poorly drained arid areas or over-irrigated canal tracts  3. Hot, humid tropics with heavy rain  4. Semi-arid and arid regions where evaporation exceeds rainfall","options":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":2,"explanation":"Heavy rain and heat leach silica (laterisation); low rain leaves calcium carbonate in the profile (calcification); acidic leaching under conifers gives podzols; capillary rise and evaporation concentrate salts (salinisation).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-134","question":"Tube-well irrigation is far more widespread in the northern plains than on the Deccan plateau mainly because:","options":["the plains receive more rain than any part of the plateau","porous alluvium stores much groundwater; hard rock holds little","peninsular rivers are perennial, so wells are unnecessary there","the black soils of the plateau are too sandy to hold any water"],"answer":1,"explanation":"Thick, porous alluvium forms vast aquifers that are easy to tap, whereas groundwater in the hard rocks of the plateau is confined to cracks, so the peninsula relies more on tanks.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"geo-soils-agriculture-135","question":"Match the cause of land degradation with the states where NCERT says it is a major problem. A. Deforestation due to mining  B. Overgrazing  C. Over-irrigation; 1. Punjab, Haryana and western Uttar Pradesh  2. Jharkhand, Chhattisgarh, Madhya Pradesh and Odisha  3. Gujarat, Rajasthan, Madhya Pradesh and Maharashtra","options":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"answer":0,"explanation":"Mining in the mineral-rich states strips forests; pastoral dry regions suffer overgrazing; and over-irrigation in the Green Revolution belt causes waterlogging, salinity and alkalinity.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-136","question":"Match the form of water erosion with its description. A. Sheet erosion  B. Rill erosion  C. Gully erosion  D. Ravines (badlands); 1. Many small finger-like channels cut by runoff  2. Uniform removal of a thin layer of topsoil over a large area  3. Deep channels that cannot be crossed by a plough  4. Land so cut up by deep gullies that it is unfit for cultivation, as along the Chambal","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Erosion progresses from almost invisible sheet wash, to rills, to gullies, to a network of ravines. Sheet erosion is the most dangerous early stage because it goes unnoticed.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-137","question":"Which of these crops grows best on distinctly acidic soils, so that heavy liming of its fields would harm it?","options":["Cotton","Sugarcane","Barley","Tea"],"answer":3,"explanation":"Tea prefers acidic soils of about pH 4.5–5.5, which is why it thrives on the leached hill soils of Assam and Darjeeling. Barley is notable for tolerating saline, alkaline conditions.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-138","question":"'Khaira' disease of rice, with rusty brown patches on the leaves and stunted growth, is caused by a deficiency of:","options":["iron","nitrogen","zinc","boron"],"answer":2,"explanation":"Khaira was identified in the Tarai of Uttar Pradesh as zinc deficiency in flooded rice and is corrected with zinc sulphate. It is a classic example of a micronutrient disorder.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-139","question":"Which of these crops was NOT brought to India from the Americas?","options":["Maize","Chilli pepper","Potato","Sugarcane"],"answer":3,"explanation":"Maize, chilli and potato are New World crops introduced after 1500, largely through the Portuguese. Sugarcane was cultivated in India since ancient times, which is why the word 'sugar' traces back to Sanskrit 'sharkara'.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-soils-agriculture-140","question":"The sub-division and fragmentation of farm holdings in India is caused mainly by:","options":["equal division of land among heirs","the Green Revolution demand for large farms","the consolidation of holdings (chakbandi)","shifting cultivation in the plains"],"answer":0,"explanation":"Each generation divides land among heirs, often plot by plot, creating small scattered fields. Consolidation (chakbandi) is the remedy, not the cause.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-141","question":"Berseem (Egyptian clover), widely grown in north India, is best described as a:","options":["kharif fodder grass grown with maize","rabi fodder legume that fixes nitrogen","perennial plantation crop of the hills","kharif oilseed of the dry Deccan"],"answer":1,"explanation":"Berseem is sown in October–November and cut several times through winter, giving protein-rich green fodder; being a legume, it also fixes nitrogen, so it fits well before kharif crops.","difficulty":"hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-142","question":"Which of these is NOT counted under 'foodgrains' in Indian agricultural statistics?","options":["Gram (chana)","Bajra","Barley","Groundnut"],"answer":3,"explanation":"Foodgrains comprise cereals (rice, wheat, coarse cereals such as bajra and barley) and pulses such as gram. Groundnut is an oilseed and is reported separately.","difficulty":"very-hard","source":"SSC CGL Tier 2"},
  {"id":"geo-soils-agriculture-143","question":"In Indian agricultural statistics, the agricultural year runs from:","options":["January to December","April to March","July to June","October to September"],"answer":2,"explanation":"The agricultural year starts in July with kharif sowing and ends in June after the rabi harvest. April–March is the financial year, which is the usual trap.","difficulty":"hard","source":"SSC CGL Tier 2"},
];

export default questions;
